:root {
  --ink: #27323a;
  --paper: #fffdf7;
  --navy: #244c66;
  --sky: #dceef3;
  --sun: #f5c84b;
  --line: #cbd8dc;
  --mint: #d9eee3;
}

* {
  box-sizing: border-box;
}

.repair-ticket {
  width: 460px;
  overflow: hidden;
  border: 2px solid var(--navy);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.ticket-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px;
  background: var(--sky);
  border-bottom: 2px solid var(--navy);
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--navy);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 1px;
}

.ticket-head h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1;
}

.claim-number {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--sun);
  color: var(--navy);
  font-size: 13px;
  font-weight: 800;
}

.item-row {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 15px 16px;
}

.umbrella-mark {
  font-size: 30px;
}

.item-copy {
  margin: 0;
  font-size: 14px;
  line-height: 1.45;
}

.ticket-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  border-top: 1px dashed var(--line);
  font-size: 13px;
}

.status {
  padding: 5px 8px;
  border-radius: 4px;
  background: var(--mint);
  color: var(--navy);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.6px;
}
